use crate::handler::middleware::clientaddr::ClientAddr;
use crate::proxy::active_call_registry::ActiveProxyCallRegistry;
use crate::proxy::server::SipServerRef;
use crate::rwi::auth::{RwiAuth, RwiIdentity};
use crate::rwi::gateway::RwiGateway;
use crate::rwi::processor::RwiCommandProcessor;
use crate::rwi::proto::{ResponseStatus, RwiError, RwiResponse};
use crate::rwi::session::{OwnershipMode, RwiCommandMessage, RwiCommandPayload};
use axum::{
    Extension,
    extract::Query,
    extract::ws::{Message, WebSocket, WebSocketUpgrade},
    http::{HeaderMap, StatusCode, header},
    response::IntoResponse,
};
use futures::{SinkExt, StreamExt};
use std::sync::Arc;
use tokio::sync::RwLock;
use tokio::sync::mpsc;

pub async fn rwi_ws_handler(
    _client_addr: ClientAddr,
    ws: WebSocketUpgrade,
    Query(params): Query<std::collections::HashMap<String, String>>,
    Extension(auth): Extension<Arc<RwLock<RwiAuth>>>,
    Extension(gateway): Extension<Arc<RwLock<RwiGateway>>>,
    Extension(call_registry): Extension<Arc<ActiveProxyCallRegistry>>,
    Extension(sip_server): Extension<Option<SipServerRef>>,
    headers: HeaderMap,
) -> impl IntoResponse {
    let token = extract_token(&headers, &params);

    let identity = match token {
        Some(t) => {
            let auth = auth.read().await;
            auth.validate_token(&t)
        }
        None => None,
    };

    let identity = match identity {
        Some(i) => i,
        None => {
            return (
                StatusCode::UNAUTHORIZED,
                [(
                    header::WWW_AUTHENTICATE,
                    r#"Bearer realm="rwi", error="invalid_token""#,
                )],
            )
                .into_response();
        }
    };

    ws.protocols(["rwi-v1"])
        .on_upgrade(async move |socket| {
            handle_websocket(socket, identity, gateway, call_registry, sip_server).await;
        })
        .into_response()
}

fn extract_token(
    headers: &HeaderMap,
    query_params: &std::collections::HashMap<String, String>,
) -> Option<String> {
    if let Some(auth_header) = headers.get("authorization") {
        if let Ok(auth_str) = auth_header.to_str() {
            if auth_str.starts_with("Bearer ") {
                return Some(auth_str[7..].to_string());
            }
        }
    }

    query_params.get("token").cloned()
}

/// Single unified WebSocket session loop.
///
/// Architecture:
/// ```text
///   ws_receiver -> [recv_task]
///                      | parse + process command
///                      | build RwiResponse JSON
///                      v
///                  [ws_tx channel]  <- gateway event fan-out also writes here
///                      |
///                  [write_task] -> ws_sender
/// ```
async fn handle_websocket(
    socket: WebSocket,
    identity: RwiIdentity,
    gateway: Arc<RwLock<RwiGateway>>,
    call_registry: Arc<ActiveProxyCallRegistry>,
    sip_server: Option<SipServerRef>,
) {
    let (mut ws_sender, mut ws_receiver) = socket.split();

    let (ws_tx, mut ws_rx) = mpsc::unbounded_channel::<String>();

    let processor = {
        let p = RwiCommandProcessor::new(call_registry, gateway.clone());
        let p = if let Some(server) = sip_server {
            p.with_sip_server(server)
        } else {
            p
        };
        Arc::new(p)
    };

    let session_id = {
        let mut gw = gateway.write().await;
        let session = gw.create_session(identity.clone());
        let id = session.read().await.id.clone();
        let (event_tx, mut event_rx) = mpsc::unbounded_channel::<serde_json::Value>();
        let ws_tx_clone = ws_tx.clone();
        tokio::spawn(async move {
            while let Some(v) = event_rx.recv().await {
                if let Ok(s) = serde_json::to_string(&v) {
                    let _ = ws_tx_clone.send(s);
                }
            }
        });
        gw.set_session_event_sender(&id, event_tx);
        id
    };

    let write_task = tokio::spawn(async move {
        while let Some(msg) = ws_rx.recv().await {
            if ws_sender.send(Message::Text(msg.into())).await.is_err() {
                break;
            }
        }
    });

    let (command_tx, _command_rx) = mpsc::unbounded_channel::<RwiCommandMessage>();

    let session_id_clone = session_id.clone();
    let gateway_clone = gateway.clone();
    let ws_tx_resp = ws_tx.clone();
    let recv_task = tokio::spawn(async move {
        while let Some(msg) = ws_receiver.next().await {
            match msg {
                Ok(Message::Text(text)) => {
                    let text = text.to_string();
                    let response_json = handle_text_message(
                        &text,
                        &command_tx,
                        processor.clone(),
                        &session_id_clone,
                        gateway_clone.clone(),
                    )
                    .await;
                    if let Some(json) = response_json {
                        let _ = ws_tx_resp.send(json);
                    }
                }
                Ok(Message::Close(_)) => break,
                Err(_) => break,
                _ => {}
            }
        }
    });

    tokio::select! {
        _ = write_task => {}
        _ = recv_task => {}
    }

    let mut gw = gateway.write().await;
    gw.remove_session(&session_id).await;
}

/// Process one text frame from the WebSocket.
///
/// Returns the JSON string to send back as a response (always — even for errors).
async fn handle_text_message(
    text: &str,
    command_tx: &mpsc::UnboundedSender<RwiCommandMessage>,
    processor: Arc<RwiCommandProcessor>,
    session_id: &str,
    gateway: Arc<RwLock<RwiGateway>>,
) -> Option<String> {
    let value: serde_json::Value = match serde_json::from_str(text) {
        Ok(v) => v,
        Err(e) => {
            return error_response("", "parse_error", e.to_string());
        }
    };

    let action = match value.get("action").and_then(|v| v.as_str()) {
        Some(a) => a.to_string(),
        None => {
            return error_response("", "missing_action", "action field required");
        }
    };

    let action_id = value
        .get("action_id")
        .and_then(|v| v.as_str())
        .map(String::from)
        .unwrap_or_else(|| uuid::Uuid::new_v4().to_string());

    let params = value.get("params").unwrap_or(&serde_json::Value::Null);

    let command = match parse_action(&action, params) {
        Ok(cmd) => cmd,
        Err(msg) => {
            return error_response(&action_id, "unknown_action", msg);
        }
    };

    match &command {
        RwiCommandPayload::Subscribe { contexts } => {
            let mut gw = gateway.write().await;
            gw.subscribe(&session_id.to_string(), contexts.clone())
                .await;
        }
        RwiCommandPayload::Unsubscribe { contexts } => {
            let mut gw = gateway.write().await;
            gw.unsubscribe(&session_id.to_string(), contexts).await;
        }
        RwiCommandPayload::DetachCall { call_id } => {
            let mut gw = gateway.write().await;
            if gw
                .release_call_ownership(&session_id.to_string(), call_id)
                .await
            {
                gw.detach_supervisor(&session_id.to_string(), call_id).await;
            }
        }
        _ => {}
    }

    let call_id = extract_call_id(&command);

    let result = processor.process_command(command).await;

    let _ = command_tx.send(RwiCommandMessage {
        id: action_id.clone(),
        call_id,
        command: RwiCommandPayload::ListCalls,
    });

    let resp = match result {
        Ok(cmd_result) => {
            let data = match cmd_result {
                crate::rwi::processor::CommandResult::ListCalls(calls) => {
                    serde_json::to_value(calls).ok()
                }
                crate::rwi::processor::CommandResult::CallFound { call_id } => {
                    Some(serde_json::json!({ "call_id": call_id }))
                }
                crate::rwi::processor::CommandResult::Originated { call_id } => {
                    {
                        let mut gw = gateway.write().await;
                        let _ = gw
                            .claim_call_ownership(
                                &session_id.to_string(),
                                call_id.clone(),
                                OwnershipMode::Control,

use crate::rwi::auth::RwiIdentity;
use crate::rwi::proto::RwiEvent;
use crate::rwi::session::{OwnershipMode, RwiSession, SupervisorMode};
use std::collections::{HashMap, HashSet};
use std::sync::{Arc, Arc as StdArc};
use tokio::sync::{RwLock, mpsc};

pub type SessionId = String;
pub type CallId = String;
pub type Context = String;

/// Sender for pushing JSON-serialized events to a WebSocket session.
pub type WsEventSender = mpsc::UnboundedSender<serde_json::Value>;

#[derive(Debug, Clone)]
pub struct GatewayState {
    pub session_id: SessionId,
    pub call_id: CallId,
    pub context: Option<Context>,
    pub ownership: Option<OwnershipMode>,
    pub supervisor_mode: Option<SupervisorMode>,
}

pub type RwiGatewayRef = StdArc<RwLock<RwiGateway>>;

pub struct RwiGateway {
    sessions: HashMap<SessionId, Arc<RwLock<RwiSession>>>,
    /// Per-session WebSocket event senders.
    session_event_senders: HashMap<SessionId, WsEventSender>,
    context_subscriptions: HashMap<Context, HashSet<SessionId>>,
    call_ownership: HashMap<CallId, SessionId>,
    supervisor_calls: HashMap<CallId, SessionId>,
}

#[derive(Debug, Clone)]
pub struct RwiEventMessage {
    pub call_id: CallId,
    pub event: RwiEvent,
    pub target_sessions: Vec<SessionId>,
}

impl RwiGateway {
    pub fn new() -> Self {
        Self {
            sessions: HashMap::new(),
            session_event_senders: HashMap::new(),
            context_subscriptions: HashMap::new(),
            call_ownership: HashMap::new(),
            supervisor_calls: HashMap::new(),
        }
    }

    /// Create a new RWI session and return the Arc handle.
    /// The caller must call [`set_session_event_sender`] with the WS sender after this.
    pub fn create_session(&mut self, identity: RwiIdentity) -> Arc<RwLock<RwiSession>> {
        let (command_tx, _command_rx) = tokio::sync::mpsc::unbounded_channel();
        let session = RwiSession::new(identity, command_tx);
        let session_id = session.id.clone();
        let session = Arc::new(RwLock::new(session));
        self.sessions.insert(session_id.clone(), session.clone());
        session
    }

    /// Register the WebSocket event sender for a session so that `send_event`
    /// and `fan_out_event_to_context` can deliver events to it.
    pub fn set_session_event_sender(&mut self, session_id: &SessionId, sender: WsEventSender) {
        self.session_event_senders
            .insert(session_id.clone(), sender);
    }

    pub async fn remove_session(&mut self, session_id: &SessionId) {
        self.session_event_senders.remove(session_id);
        if let Some(session) = self.sessions.remove(session_id) {
            let session = session.read().await;
            for ctx in &session.subscribed_contexts {
                if let Some(subs) = self.context_subscriptions.get_mut(ctx) {
                    subs.remove(session_id);
                }
            }
            for call_id in session.owned_calls.keys() {
                self.call_ownership.remove(call_id);
            }
            for call_id in session.supervisor_targets.keys() {
                self.supervisor_calls.remove(call_id);
            }
        }
    }

    pub async fn subscribe(&mut self, session_id: &SessionId, contexts: Vec<Context>) -> bool {
        if let Some(session) = self.sessions.get(session_id) {
            let mut session = session.write().await;
            session.subscribe(contexts.clone());
            for ctx in contexts {
                self.context_subscriptions
                    .entry(ctx)
                    .or_insert_with(HashSet::new)
                    .insert(session_id.clone());
            }
            true
        } else {
            false
        }
    }

    pub async fn unsubscribe(&mut self, session_id: &SessionId, contexts: &[Context]) -> bool {
        if let Some(session) = self.sessions.get(session_id) {
            let mut session = session.write().await;
            session.unsubscribe(contexts);
            for ctx in contexts {
                if let Some(subs) = self.context_subscriptions.get_mut(ctx) {
                    subs.remove(session_id);
                }
            }
            true
        } else {
            false
        }
    }

    pub async fn claim_call_ownership(
        &mut self,
        session_id: &SessionId,
        call_id: CallId,
        mode: OwnershipMode,
    ) -> Result<(), ClaimError> {
        if let Some(current_owner) = self.call_ownership.get(&call_id) {
            if current_owner != session_id {
                return Err(ClaimError::AlreadyOwned);
            }
        }

        if let Some(session) = self.sessions.get(session_id) {
            let mut session = session.write().await;
            if session.claim_call(call_id.clone(), mode) {
                self.call_ownership.insert(call_id, session_id.clone());
                return Ok(());
            }
            Err(ClaimError::AlreadyOwned)
        } else {
            Err(ClaimError::SessionNotFound)
        }
    }

    pub async fn release_call_ownership(
        &mut self,
        session_id: &SessionId,
        call_id: &CallId,
    ) -> bool {
        if let Some(current_owner) = self.call_ownership.get(call_id) {
            if current_owner != session_id {
                return false;
            }
        }

        if let Some(session) = self.sessions.get(session_id) {
            let mut session = session.write().await;
            if session.release_call(call_id) {
                self.call_ownership.remove(call_id);
                return true;
            }
        }
        false
    }

    pub async fn attach_supervisor(
        &mut self,
        session_id: &SessionId,
        target_call_id: CallId,
        mode: SupervisorMode,
    ) -> bool {
        if let Some(session) = self.sessions.get(session_id) {
            let mut session = session.write().await;
            session.add_supervisor_target(target_call_id.clone(), mode);
            self.supervisor_calls
                .insert(target_call_id, session_id.clone());
            true
        } else {
            false
        }
    }

    pub async fn detach_supervisor(
        &mut self,
        session_id: &SessionId,
        target_call_id: &CallId,
    ) -> bool {
        if let Some(session) = self.sessions.get(session_id) {
            let mut session = session.write().await;
            if session.remove_supervisor_target(target_call_id) {
                self.supervisor_calls.remove(target_call_id);
                return true;
            }
        }
        false
    }

    pub fn get_call_owner(&self, call_id: &CallId) -> Option<SessionId> {
        self.call_ownership.get(call_id).cloned()
    }

    pub fn is_supervisor(&self, call_id: &CallId) -> bool {
        self.supervisor_calls.contains_key(call_id)
    }

    pub fn get_supervisor_session(&self, call_id: &CallId) -> Option<SessionId> {
        self.supervisor_calls.get(call_id).cloned()
    }

    pub fn get_sessions_subscribed_to_context(&self, context: &str) -> Vec<SessionId> {
        self.context_subscriptions
            .get(context)
            .map(|s| s.iter().cloned().collect())
            .unwrap_or_default()
    }

    pub fn get_all_sessions(&self) -> Vec<SessionId> {
        self.sessions.keys().cloned().collect()
    }

    pub fn session_count(&self) -> usize {
        self.sessions.len()
    }

    pub fn call_count(&self) -> usize {
        self.call_ownership.len()
    }

    /// Send an event to a single session by session_id.
    pub fn send_event_to_session(&self, session_id: &SessionId, event: &RwiEvent) {
        if let Some(sender) = self.session_event_senders.get(session_id) {
            if let Ok(value) = serde_json::to_value(event) {
                let _ = sender.send(value);
            }
        }
    }

    /// Send an event to the owner of a call_id (if any).
    pub fn send_event_to_call_owner(&self, call_id: &CallId, event: &RwiEvent) {
        if let Some(owner_id) = self.call_ownership.get(call_id) {
            self.send_event_to_session(owner_id, event);
        }
    }

    /// Fan-out an event to all sessions subscribed to a context.
    /// Used for inbound `call.incoming` notifications.
    pub fn fan_out_event_to_context(&self, context: &str, event: &RwiEvent) {
        if let Some(subscribers) = self.context_subscriptions.get(context) {
            for session_id in subscribers {
                self.send_event_to_session(session_id, event);
            }
        }
    }

    /// Send an event to every known session (broadcast).
    pub fn broadcast_event(&self, event: &RwiEvent) {
        for session_id in self.session_event_senders.keys() {
            self.send_event_to_session(session_id, event);
        }
    }
}

