#[allow(dead_code)]
impl RwiCommandProcessor {
    pub fn new(
        call_registry: Arc<ActiveProxyCallRegistry>,
        gateway: Arc<RwLock<RwiGateway>>,
    ) -> Self {
        Self {
            call_registry,
            gateway,
            sip_server: None,
