592	                Ok(_) => info!("Server shut down gracefully"),
593	                Err(e) => {
594	                    tracing::error!("Server error: {}", e);
595	                    return Err(anyhow::anyhow!("Server error: {}", e));
596	                }
597	            }
598	        }
599	        https_result = async {
600	            if let (Some(config), Some(addr)) = (https_config, https_addr) {
601	                 axum_server::bind_rustls(addr, config)
602	                    .serve(https_router.into_make_service_with_connect_info::<SocketAddr>())
603	                    .await
604	            } else {
605	                std::future::pending().await
606	            }
607	        } => {
608	             match https_result {
609	                Ok(_) => info!("HTTPS Server shut down gracefully"),
610	                Err(e) => {
611	                    tracing::error!("HTTPS Server error: {}", e);
612	                    return Err(anyhow::anyhow!("HTTPS Server error: {}", e));
613	                }
614	            }
615	        }
616	        prx_result = state.sip_server().serve()  => {
617	            if let Err(e) = prx_result {
618	                tracing::error!("Sip server error: {}", e);
619	            }
620	        }
621	        _ = token.cancelled() => {
622	            info!("Application shutting down due to cancellation");
623	        }
624	    }
625	    Ok(())
626	}
