634	pub fn create_router(state: AppState) -> Router {
635	    let mut router = Router::new();
636	
637	    // Serve static files
638	    let static_files_service = ServeDir::new("static");
639	
640	    // If static/index.html exists, serve it at the root
641	    if std::path::Path::new("static/index.html").exists() {
642	        router = router.route(
643	            "/",
644	            get(|| async {
645	                match tokio::fs::read_to_string("static/index.html").await {
646	                    Ok(content) => Html(content).into_response(),
647	                    Err(_) => StatusCode::NOT_FOUND.into_response(),
648	                }
649	            }),
650	        );
651	    }
652	
653	    // CORS configuration to allow cross-origin requests
654	    let cors = CorsLayer::new()
655	        .allow_origin(AllowOrigin::any())
656	        .allow_methods([
657	            axum::http::Method::GET,
658	            axum::http::Method::POST,
659	            axum::http::Method::PUT,
660	            axum::http::Method::DELETE,
661	            axum::http::Method::OPTIONS,
662	        ])
663	        .allow_headers([
664	            axum::http::header::CONTENT_TYPE,
665	            axum::http::header::AUTHORIZATION,
666	            axum::http::header::ACCEPT,
667	            axum::http::header::ORIGIN,
668	        ]);
669	
670	    // Merge call and WebSocket handlers with static file serving
671	    let call_routes = crate::handler::ami_router(state.clone()).with_state(state.clone());
672	    #[allow(unused_mut)]
673	    let mut router = router
674	        .route(
675	            "/iceservers",
676	            get(iceservers_handler).with_state(state.clone()),
677	        )
678	        .merge(state.addon_registry.get_routers(state.clone()))
679	        .nest_service("/static", static_files_service)
680	        .merge(call_routes)
681	        .layer(cors);
682	
683	    // Add RWI WebSocket endpoint if configured
684	    if let (Some(auth), Some(gateway), Some(call_registry)) = (
685	        state.core.rwi_auth.clone(),
686	        state.core.rwi_gateway.clone(),
687	        state.core.rwi_call_registry.clone(),
688	    ) {
689	        let rwi_auth = auth;
690	        let rwi_gateway = gateway;
691	        let rwi_call_registry = call_registry;
692	        let rwi_sip_server: Option<crate::proxy::server::SipServerRef> =
693	            Some(state.sip_server().get_inner());
694	        router = router.route(
695	            "/rwi/v1",
696	            axum::routing::get(
697	                async move |client_addr: crate::handler::middleware::clientaddr::ClientAddr,
698	                            ws: axum::extract::ws::WebSocketUpgrade,
699	                            axum::extract::Query(params): axum::extract::Query<
700	                    std::collections::HashMap<String, String>,
701	                >,
702	                            headers: axum::http::HeaderMap| {
703	                    use axum::Extension;
704	                    use axum::extract::Query;
705	
706	                    crate::rwi::handler::rwi_ws_handler(
707	                        client_addr,
708	                        ws,
709	                        Query(params),
710	                        Extension(rwi_auth),
711	                        Extension(rwi_gateway),
712	                        Extension(rwi_call_registry),
713	                        Extension(rwi_sip_server),
714	                        headers,
715	                    )
716	                    .await
717	                },
718	            ),
719	        );
720	    }
721	
722	    #[cfg(feature = "console")]
723	    if let Some(console_state) = state.console.clone() {
724	        router = router.merge(crate::console::router(console_state));
725	    }
726	
727	    let access_log_skip_paths = Arc::new(state.config().http_access_skip_paths.clone());
728	
729	    router = router.layer(middleware::from_fn_with_state(
730	        access_log_skip_paths,
731	        crate::handler::middleware::request_log::log_requests,
732	    ));
733	
734	    if state.config().http_gzip {
735	        router = router.layer(CompressionLayer::new().gzip(true));
736	    }
737	
738	    router
739	}

