  2	//!
  3	//! This module provides a unified entry point for dispatching commands to sessions.
  4	//! It supports both the legacy SessionAction path and the new unified CallCommand path.
  5	//!
  6	//! ## Usage
  7	//!
  8	//! ```rust,ignore
  9	//! use crate::call::runtime::command_dispatch::dispatch_command;
 10	//!
 11	//! // Convert RWI payload to CallCommand and dispatch
 12	//! let result = dispatch_command(
 13	//!     &registry,
 14	//!     session_id,
 15	//!     rwi_payload,
 16	//!     CommandSource::Rwi,
 17	//! ).await;
 18	//! ```
