 28	/// Dispatch an RWI command using the unified path
 29	///
 30	/// This function:
 31	/// 1. Converts RwiCommandPayload to CallCommand
 32	/// 2. Checks media capabilities
 33	/// 3. Dispatches to the session
 34	pub fn dispatch_rwi_command(
 35	    registry: &Arc<ActiveProxyCallRegistry>,
 36	    session_id: Option<&str>,
 37	    payload: RwiCommandPayload,
 38	) -> anyhow::Result<CommandResult> {
 39	    // Step 1: Convert to CallCommand
 40	    let command = match rwi_to_call_command(payload, session_id) {
 41	        Ok(cmd) => cmd,
 42	        Err(e) => {
 43	            // Some RWI commands are not convertible to CallCommand (session management, etc.)
 44	            // Return a special result indicating the command should be handled by legacy path
 45	            return Ok(CommandResult::failure(format!(
 46	                "command not supported by unified path: {}",
 47	                e
 48	            )));
 49	        }
 50	    };
 51	
 52	    // Step 2: Create execution context
 53	    let session_id = session_id.unwrap_or_default();
 54	    let ctx = ExecutionContext::new(session_id)
 55	        .with_source(CommandSource::Rwi);
 56	
 57	    // Step 3: Check media capabilities
 58	    match ctx.check_media_capability(&command) {
 59	        MediaCapabilityCheck::Denied { reason } => {
 60	            return Ok(CommandResult::not_supported(reason));
 61	        }
 62	        MediaCapabilityCheck::Degraded { reason: _ } => {
 63	            // Command can execute but with degraded functionality
 64	            // Continue execution, the result will indicate degradation
 65	        }
 66	        MediaCapabilityCheck::Allowed => {}
 67	    }
 68	
 69	    // Step 4: Dispatch to session
 70	    dispatch_command(registry, &session_id, command)
 71	}
