127	/// Internal: Dispatch a CallCommand to a session
128	fn dispatch_command(
129	    registry: &Arc<ActiveProxyCallRegistry>,
130	    session_id: &str,
131	    command: CallCommand,
132	) -> anyhow::Result<CommandResult> {
133	    // Special handling for Bridge command: check session exists
134	    if let CallCommand::Bridge { .. } = &command {
135	        // For Bridge, we need to verify the session has both legs
136	        // The legs are identified by leg_a and leg_b within the same session
137	        let Some(handle) = registry.get_handle(session_id) else {
138	            return Ok(CommandResult::failure(format!(
139	                "session {} not found",
140	                session_id
141	            )));
142	        };
143	        // Send the bridge command
144	        match handle.send_command(command) {
145	            Ok(_) => return Ok(CommandResult::success()),
146	            Err(e) => return Ok(CommandResult::failure(format!("failed to dispatch: {}", e))),
147	        }
148	    }
149	
150	    // Get the session handle from registry
151	    let Some(handle) = registry.get_handle(session_id) else {
152	        return Ok(CommandResult::failure(format!(
153	            "session {} not found",
154	            session_id
155	        )));
156	    };
157	
158	    // Send the command to the session's event loop
159	    match handle.send_command(command) {
160	        Ok(_) => Ok(CommandResult::success()),
161	        Err(e) => Ok(CommandResult::failure(format!("failed to dispatch: {}", e))),
162	    }
163	}
