111	    fn get_fallback_action(&self, action: &FailureAction) -> AppAction {
112	        match action {
113	            FailureAction::Hangup { code, reason } => {
114	                info!(?code, ?reason, "Queue: hangup fallback");
115	                AppAction::Hangup {
116	                    reason: reason
117	                        .as_ref()
118	                        .map(|_| CallRecordHangupReason::ServerUnavailable),
119	                    code: code.as_ref().map(|c| c.code()),
120	                }
121	            }
122	            FailureAction::PlayThenHangup {
123	                audio_file: _,
124	                use_early_media: _,
125	                status_code,
126	                reason,
127	            } => {
128	                info!("Queue: play then hangup fallback");
129	                // For simplicity, just hangup (play could be added if needed)
130	                AppAction::Hangup {
131	                    reason: reason
132	                        .as_ref()
133	                        .map(|_| CallRecordHangupReason::ServerUnavailable),
134	                    code: Some(status_code.code()),
135	                }
136	            }
137	            FailureAction::Transfer(endpoint) => {
138	                info!(target = ?endpoint, "Queue: transfer fallback");
139	                // Transfer to the endpoint
140	                match endpoint {
141	                    crate::call::TransferEndpoint::Uri(uri) => {
