28	pub fn prepare_sqlite_database(database_url: &str) -> Result<()> {
29	    let Some(path_part) = database_url.strip_prefix("sqlite://") else {
30	        return Ok(());
31	    };
32	
33	    let (path_str, _) = path_part.split_once('?').unwrap_or((path_part, ""));
34	    if path_str.is_empty() || path_str.starts_with(':') {
35	        return Ok(());
36	    }
37	
38	    let path = std::path::Path::new(path_str);
39	    if let Some(parent) = path.parent() {
40	        if !parent.as_os_str().is_empty() {
41	            std::fs::create_dir_all(parent).with_context(|| {
42	                format!(
43	                    "failed to create directory for console database at {}",
44	                    parent.display()
45	                )
46	            })?;
47	        }
48	    }
49	
50	    if !path.exists() {
51	        std::fs::OpenOptions::new()
52	            .create(true)
53	            .write(true)
54	            .open(path)
55	            .with_context(|| {
56	                format!(
57	                    "failed to create console database file at {}",
58	                    path.display()
59	                )
60	            })?;
61	    }
62	
63	    Ok(())
64	}
65	
66	pub async fn create_db(database_url: &str) -> Result<DatabaseConnection> {
67	    if database_url.starts_with("sqlite://") {
68	        prepare_sqlite_database(database_url).map_err(|e| {
69	            tracing::error!("failed to prepare SQLite database {database_url} {:?}", e);
70	            let msg = format!("failed to prepare SQLite database {database_url}: {e}");
71	            anyhow::anyhow!(msg)
72	        })?;
73	    }
74	
75	    let db = Database::connect(database_url)
76	        .await
77	        .map_err(|e: sea_orm::DbErr| {
78	            tracing::error!("failed to connect to database {:?}", e);
79	            let msg = format!("failed to connect to database {database_url}: {e}");
80	            anyhow::anyhow!(msg)
81	        })?;
82	
83	    migration::Migrator::up(&db, None).await.map_err(|e| {
84	        tracing::error!("failed to run database migrations on {:?}", e);
85	        let msg = format!("failed to run database migrations on {database_url}: {e}");
86	        anyhow::anyhow!(msg)
87	    })?;
88	    Ok(db)
89	}

