171	    pub async fn list(&self, prefix: Option<&str>) -> Result<Vec<ObjectMeta>> {
172	        let prefix = prefix
173	            .map(|p| self.object_path(p))
174	            .unwrap_or_else(|| self.object_path(""));
175	        let mut stream = self.inner.list(Some(&prefix));
176	        let mut files = Vec::new();
177	        while let Some(item) = stream.next().await {
178	            let meta = item?;
179	            files.push(meta);
