196	    // Helper to upload a local file to storage (move)
197	    pub async fn upload_file(&self, local_path: &PathBuf, remote_path: &str) -> Result<()> {
198	        if self.is_local {
199	            let dest = self.local_path(remote_path).unwrap();
200	            if let Some(parent) = dest.parent() {
201	                tokio::fs::create_dir_all(parent).await?;
202	            }
203	            // If src and dest are the same, do nothing
204	            if local_path != &dest {
205	                tokio::fs::rename(local_path, dest).await?;
206	            }
207	        } else {
208	            let data = tokio::fs::read(local_path).await?;
209	            self.write(remote_path, Bytes::from(data)).await?;
210	            tokio::fs::remove_file(local_path).await?;
211	        }
212	        Ok(())
213	    }
214	}
