135	        let recorder_root = self.config().recorder_path();
136	        let root = Path::new(&recorder_root);
137	        if !root.exists() {
138	            match std::fs::create_dir_all(root) {
139	                Ok(_) => {
140	                    info!("created recorder root: {}", root.to_string_lossy());
141	                }
142	                Err(e) => {
143	                    warn!(
144	                        "Failed to create recorder root: {} {}",
145	                        e,
146	                        root.to_string_lossy()
147	                    );
148	                }
149	            }
150	        }
151	        let mut recorder_file = root.join(sanitized_id);
152	        recorder_file.set_extension("wav");
153	        recorder_file.to_string_lossy().to_string()
154	    }
155	}
