206	    pub async fn build(self) -> Result<AppState> {
207	        let config: Arc<Config> = Arc::new(self.config.unwrap_or_default());
208	        let storage_config = config.storage.clone().unwrap_or_default();
209	        let storage = crate::storage::Storage::new(&storage_config)?;
210	
211	        let token = self
212	            .cancel_token
213	            .unwrap_or_else(|| CancellationToken::new());
214	        let config_loaded_at = self.config_loaded_at.unwrap_or_else(|| Utc::now());
215	        let config_path = self.config_path.clone();
216	        let db_conn = crate::models::create_db(&config.database_url).await?;
217	
218	        let addon_registry = Arc::new(crate::addons::registry::AddonRegistry::new());
219	
220	        // Pre-build the SipFlow backend so it can be shared between the SipServer
221	        // (for recording RTP packets) and the SipFlowUploadHook (for post-call upload).
222	        // Building it here ensures only one backend instance is ever created for a given
223	        // spool directory, avoiding concurrent SQLite writes.
224	        let sipflow_backend_arc: Option<Arc<dyn crate::sipflow::SipFlowBackend>> =
225	            config.sipflow.as_ref().and_then(|cfg| {
226	                crate::sipflow::backend::create_backend(cfg)
227	                    .map(|b| Arc::from(b) as Arc<dyn crate::sipflow::SipFlowBackend>)
228	                    .map_err(|e| warn!("Failed to create sipflow backend: {e}"))
229	                    .ok()
230	            });
231	
232	        // The upload hook is wired in when [sipflow.upload] is configured.
233	        let sipflow_upload_config: Option<crate::config::SipFlowUploadConfig> =
234	            config.sipflow.as_ref().and_then(|s| match s {
235	                crate::config::SipFlowConfig::Local { upload, .. } => upload.clone(),
236	                _ => None,
237	            });
238	
239	        let callrecord_formatter = if let Some(formatter) = self.callrecord_formatter {
240	            formatter
241	        } else {
242	            let formatter = if let Some(ref callrecord) = config.callrecord {
243	                DefaultCallRecordFormatter::new_with_config(callrecord)
244	            } else {
245	                DefaultCallRecordFormatter::default()
246	            };
247	            Arc::new(formatter)
248	        };
249	
250	        let mut callrecord_stats = None;
251	        let mut callrecord_manager = None;
252	        let callrecord_sender = if let Some(sender) = self.callrecord_sender {
253	            Some(sender)
254	        } else if config.callrecord.is_some() || sipflow_upload_config.is_some() {
255	            // Build a CallRecordManager when either:
256	            //  - [callrecord] is configured (CDR JSON files / S3), or
257	            //  - [sipflow.upload] is configured (post-call WAV upload)
258	            // DatabaseHook is always included so call records reach the DB.
259	            let mut builder = CallRecordManagerBuilder::new()
260	                .with_cancel_token(token.child_token())

