 33	#[derive(Default)]
 34	struct RegistryState {
 35	    entries: HashMap<String, ActiveProxyCallEntry>,
 36	    handles: HashMap<String, SipSessionHandle>,
 37	    handles_by_dialog: HashMap<String, SipSessionHandle>,
 38	    // session_id -> all registered dialog_ids (multiple dialogs per session during failover)
 39	    dialog_by_session: HashMap<String, Vec<String>>,
 40	}
 41	
 42	pub struct ActiveProxyCallRegistry {
 43	    inner: Mutex<RegistryState>,
 44	}
 45	
 46	impl ActiveProxyCallRegistry {
 47	    pub fn new() -> Self {
 48	        Self {
 49	            inner: Mutex::new(RegistryState::default()),
 50	        }
 51	    }
 52	
 53	    pub fn upsert(&self, entry: ActiveProxyCallEntry, handle: SipSessionHandle) {
 54	        let mut guard = self.inner.lock().unwrap();
 55	        guard.entries.insert(entry.session_id.clone(), entry);
 56	        guard
 57	            .handles
 58	            .insert(handle.session_id().to_string(), handle);
 59	    }
 60	
 61	    pub fn register_dialog(&self, dialog_id: String, handle: SipSessionHandle) {
 62	        let mut guard = self.inner.lock().unwrap();
 63	        guard
 64	            .dialog_by_session
 65	            .entry(handle.session_id().to_string())
 66	            .or_default()
 67	            .push(dialog_id.clone());
 68	        guard.handles_by_dialog.insert(dialog_id, handle);
 69	    }
 70	
 71	    pub fn unregister_dialog(&self, dialog_id: &str) {
 72	        let mut guard = self.inner.lock().unwrap();
 73	        if let Some(handle) = guard.handles_by_dialog.remove(dialog_id) {
 74	            if let Some(dialogs) = guard.dialog_by_session.get_mut(handle.session_id()) {
 75	                dialogs.retain(|d| d != dialog_id);
 76	                if dialogs.is_empty() {
 77	                    guard.dialog_by_session.remove(handle.session_id());
 78	                }
 79	            }
 80	        }
 81	    }
 82	
 83	    pub fn get_handle_by_dialog(&self, dialog_id: &str) -> Option<SipSessionHandle> {
 84	        let guard = self.inner.lock().unwrap();
 85	        guard.handles_by_dialog.get(dialog_id).cloned()
 86	    }
 87	
 88	    pub fn update<F>(&self, session_id: &str, updater: F)
 89	    where
 90	        F: FnOnce(&mut ActiveProxyCallEntry),
 91	    {
 92	        if let Some(entry) = self.inner.lock().unwrap().entries.get_mut(session_id) {
 93	            updater(entry);
 94	        }
 95	    }
 96	
 97	    pub fn remove(&self, session_id: &str) {
 98	        let mut guard = self.inner.lock().unwrap();
 99	        guard.entries.remove(session_id);
100	        guard.handles.remove(session_id);
101	        // Remove all dialog handles registered for this session
